import{_ as t,c as a,o,aj as n}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: FunctionsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"};function i(s,e,c,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / FunctionsAPI</p><h1 id="interface-functionsapi" tabindex="-1">Interface: FunctionsAPI <a class="header-anchor" href="#interface-functionsapi" aria-label="Permalink to “Interface: FunctionsAPI”">​</a></h1><p>Server functions, available as <code>client.functions</code>.</p><p>A function is TypeScript an app&#39;s team authored in its config tree and pushed with <code>primitive config push</code>. Invoking one runs it on the platform under the calling user&#39;s own authority and returns its result.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getstatus" tabindex="-1">getStatus() <a class="header-anchor" href="#getstatus" aria-label="Permalink to “getStatus()”">​</a></h3><blockquote><p><strong>getStatus</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>): <code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>The current status of a function run, by run id.</p><p>The answer carries one structured <code>error</code> with the platform&#39;s <code>code</code> on it, and a <code>run</code> block with the run&#39;s own fields.</p><p>A run id that is not this app&#39;s, or does not exist, is <code>NOT_FOUND &quot;Function run &lt;id&gt; not found&quot;</code>. Every other refusal — a 403 from the access gate, a 5xx — propagates as it arrived.</p><p>ONE READ, reporting what it read: the retry <code>waitFor</code> makes does not belong here, because a status read is a question about now. The thrown error carries <code>details.reason</code> for callers who need to tell the two not-founds apart — <code>&quot;instance-unseen&quot;</code> for a live run whose instance the platform cannot see yet, <code>&quot;no-run&quot;</code> for a run id that resolved to nothing.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput" tabindex="-1">TOutput <a class="header-anchor" href="#toutput" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid" tabindex="-1">runId <a class="header-anchor" href="#runid" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="invoke" tabindex="-1">invoke() <a class="header-anchor" href="#invoke" aria-label="Permalink to “invoke()”">​</a></h3><blockquote><p><strong>invoke</strong>&lt;<code>TOutput</code>, <code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Invoke a server function on the REQUEST runtime and wait for its result.</p><p>The caller picks the runtime, and the ROUTE is how it is said: this method posts to <code>functions/{key}</code>, which runs the function inside the request. Every pushed function takes this verb and <code>start</code> alike — the config says nothing about how a function runs — so there is no configuration to change and no mismatch to refuse. A function that must NOT run under one of the two tests for it in its own code with <code>assertRuntime</code>, and the platform settles that as <code>status: &quot;failed&quot;</code> with <code>errorCode: &quot;FUNCTION_RUNTIME_REFUSED&quot;</code>.</p><p><code>input</code> is sent as the request envelope&#39;s <code>rootInput</code>.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-1" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-1" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h5 id="tinput" tabindex="-1">TInput <a class="header-anchor" href="#tinput" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionInvokeOptions.html"><code>FunctionInvokeOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to “start()”">​</a></h3><blockquote><p><strong>start</strong>&lt;<code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p></blockquote><p>Start a server function on the TASK runtime and get its run id back.</p><p>The mirror of <code>invoke</code>, and the route says which: this method posts to <code>functions/{key}/start</code>. Every pushed function takes both verbs.</p><p>Follow the run with <code>getStatus</code> or <code>waitFor</code>.</p><p><code>runKey</code> makes the start idempotent per <code>(caller, contextDocId, runKey)</code>: a repeat answers the run that already exists with <code>existing: true</code>, never a second run. There is no <code>forceRerun</code> on this route.</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="tinput-1" tabindex="-1">TInput <a class="header-anchor" href="#tinput-1" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey-1" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey-1" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionStartOptions.html"><code>FunctionStartOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p><hr><h3 id="terminate" tabindex="-1">terminate() <a class="header-anchor" href="#terminate" aria-label="Permalink to “terminate()”">​</a></h3><blockquote><p><strong>terminate</strong>&lt;<code>TOutput</code>&gt;(<code>ref</code>): <code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Terminate a running function run.</p><p>A run that does not exist, or whose execution cannot be found, is a <code>NOT_FOUND</code>. A live run the platform could not stop is an <code>UNAVAILABLE</code> carrying the platform&#39;s diagnostic verbatim: it is not a run that does not exist, and the diagnostic is what a caller can act on.</p><h4 id="type-parameters-3" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-3" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-2" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-2" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref" tabindex="-1">ref <a class="header-anchor" href="#ref" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="waitfor" tabindex="-1">waitFor() <a class="header-anchor" href="#waitfor" aria-label="Permalink to “waitFor()”">​</a></h3><blockquote><p><strong>waitFor</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./../type-aliases/FunctionRunSettled.html"><code>FunctionRunSettled</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Wait for a function run to reach a terminal state.</p><p>It polls: a function run sends no status events over the WebSocket.</p><p>The interval starts short and backs off, so a function that finishes in a second is not waited out and one that sleeps for an hour is not polled thousands of times.</p><p>SETTLES on exactly <code>completed</code>, <code>failed</code> and <code>terminated</code>, which is what <a href="./../type-aliases/FunctionRunSettled.html">FunctionRunSettled</a> says its <code>status</code> is. A read reporting <code>missing</code> is a not-found — that run&#39;s execution can no longer be resolved and waiting for it to become terminal is waiting for nothing. A read reporting any other state, which a function run never has, names the status in an <code>INVALID_ARGUMENT</code> rather than waiting out the deadline.</p><p>A failed run RESOLVES with <code>status: &quot;failed&quot;</code> and its <code>error</code>; it does not throw. A transient error between polls is retried.</p><p>A NOT-FOUND IS RETRIED TOO, and how far depends on which one the platform reported. A run id <code>start</code> has just returned is safe to wait on: it is not reported missing while the run is starting or running.</p><ul><li>The run EXISTS, has not settled, and the platform cannot see its instance yet — which is what a run between its creation and its first execution looks like. Polled to your own <code>timeoutMs</code>, which is the only bound a live run&#39;s wait should have.</li><li>The run id resolves to nothing. Real, and usually permanent, but not always: a poll issued a second after a start can be answered by a replica that has not caught up with it. Retried for three seconds from the start of the wait and no longer, so a mistyped run id still fails while you are watching.</li></ul><p>Either way the wait ENDS in <code>NOT_FOUND</code>, with the same code and message the first refusal would have thrown; and a wait whose <code>timeoutMs</code> runs out while its last read was a not-found reports that <code>NOT_FOUND</code> rather than <code>WORKFLOW_WAIT_TIMEOUT</code>, which would hide it. A run that is merely slow still raises the timeout.</p><h4 id="type-parameters-4" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-4" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-3" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-3" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid-1" tabindex="-1">runId <a class="header-anchor" href="#runid-1" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionWaitOptions.html"><code>FunctionWaitOptions</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../type-aliases/FunctionRunSettled.html"><code>FunctionRunSettled</code></a>&lt;<code>TOutput</code>&gt;&gt;</p>',90)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
